css:
.sl-hero-ivy {
  background-color: var(--smartlearn-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  min-height: 85vh;
  display: flex;
  align-items: center;
  padding-block: clamp(3.5rem, 7vw, 6rem);
}
.sl-hero-ivy .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-ivy .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-hero-ivy .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-ivy .sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-hero-ivy .sl-tint-primary {
  background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, var(--smartlearn-card-bg));
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-ivy .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-ivy .sl-btn-primary:hover,
.sl-hero-ivy .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-ivy .sl-btn-outline-primary {
  background-color: transparent;
  border: 1px solid var(--smartlearn-primary);
  color: var(--smartlearn-primary);
}
.sl-hero-ivy .sl-btn-outline-primary:hover,
.sl-hero-ivy .sl-btn-outline-primary:focus-visible {
  background-color: var(--smartlearn-btn-bg);
  border-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-ivy .font-serif {
  font-family: var(--smartlearn-heading-font, Georgia, 'Times New Roman', serif);
}
.sl-hero-ivy .sl-tracking-wide {
  letter-spacing: 0.1em;
}
.sl-hero-ivy .sl-stats-bar {
  border-top: 1px solid var(--smartlearn-card-border);
}
.sl-hero-ivy .sl-stat-sep {
  border-inline-start: 1px solid var(--smartlearn-card-border);
}
.sl-hero-ivy .bg-shape-cream {
  position: absolute;
  top: 0;
  inset-inline-end: 0;
  width: 45%;
  height: 100%;
  background-color: var(--smartlearn-card-bg);
  border-inline-start: 1px solid var(--smartlearn-card-border);
  z-index: 0;
  pointer-events: none;
}
.sl-hero-ivy .img-box {
  overflow: hidden;
  border: 6px solid var(--smartlearn-bg);
  background-color: var(--smartlearn-card-bg);
}
@media (min-width: 992px) {
  .sl-hero-ivy .collage-wrapper {
    min-height: 480px;
  }
  .sl-hero-ivy .img-box {
    position: absolute;
  }
  .sl-hero-ivy .box-1 {
    width: 65%;
    height: 58%;
    top: 0;
    inset-inline-start: 0;
    z-index: 2;
  }
  .sl-hero-ivy .box-2 {
    width: 56%;
    height: 50%;
    bottom: 12%;
    inset-inline-end: 0;
    z-index: 3;
  }
  .sl-hero-ivy .box-3 {
    width: 46%;
    height: 38%;
    bottom: 0;
    inset-inline-start: 10%;
    z-index: 4;
  }
}
@media (max-width: 991px) {
  .sl-hero-ivy .bg-shape-cream {
    display: none;
  }
  .sl-hero-ivy .collage-wrapper {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.75rem;
  }
  .sl-hero-ivy .img-box {
    aspect-ratio: 4 / 3;
    border-width: 3px;
  }
}
